exports.init = (params, rng) => {
  const N = params.swarmSize ?? 100;
  const phases = [];
  const baseOmegas = [];
  const xs = [];
  const ys = [];
  for (let i = 0; i < N; i++) {
    phases.push(rng.range(0, 2 * Math.PI));
    baseOmegas.push(rng.normal(0, 1));
    xs.push(rng.range(0.05, 0.95));
    ys.push(rng.range(0.05, 0.95));
  }
  let sumCos=0,sumSin=0;
  for(let i=0;i<N;i++){ sumCos+=Math.cos(phases[i]); sumSin+=Math.sin(phases[i]); }
  const r0 = Math.sqrt(sumCos*sumCos+sumSin*sumSin)/N;
  return {
    phases,
    baseOmegas,
    xs,
    ys,
    t: 0,
    leaderPhase: rng.range(0, 2 * Math.PI),
    leaderOmega: 1.0,
    flashCounts: Array(N).fill(0),
    lastR: r0,
    lastPsi: Math.atan2(sumSin,sumCos),
    smoothedR: r0
  };
};
exports.step = (state, params, rng) => {
  let N = params.swarmSize ?? state.phases.length;
  let phases = state.phases.slice();
  let baseOmegas = state.baseOmegas.slice();
  let xs = state.xs.slice();
  let ys = state.ys.slice();
  let flashCounts = state.flashCounts.slice();
  if (N !== phases.length) {
    if (N > phases.length) {
      for (let i = phases.length; i < N; i++) {
        phases.push(rng.range(0, 2 * Math.PI));
        baseOmegas.push(rng.normal(0, 1));
        xs.push(rng.range(0.05, 0.95));
        ys.push(rng.range(0.05, 0.95));
        flashCounts.push(0);
      }
    } else {
      phases = phases.slice(0, N);
      baseOmegas = baseOmegas.slice(0, N);
      xs = xs.slice(0, N);
      ys = ys.slice(0, N);
      flashCounts = flashCounts.slice(0, N);
    }
  }
  const K = params.coupling ?? 1.0;
  const spread = params.freqSpread ?? 0.4;
  const extStrength = params.externalCue ?? 0;
  const leaderPresent = params.leaderPresent ? 1 : 0;
  const dt = 0.025;
  let sumCos = 0, sumSin = 0;
  for (let i = 0; i < N; i++) {
    sumCos += Math.cos(phases[i]);
    sumSin += Math.sin(phases[i]);
  }
  const r = Math.sqrt(sumCos * sumCos + sumSin * sumSin) / Math.max(1,N);
  const psi = Math.atan2(sumSin, sumCos);
  const extPhase = 1.0 * state.t;
  let leaderPhase = state.leaderPhase + state.leaderOmega * dt;
  leaderPhase = leaderPhase % (2 * Math.PI);
  if (leaderPhase < 0) leaderPhase += 2 * Math.PI;
  const newPhases = new Array(N);
  const newFlashCounts = flashCounts.slice();
  for (let i = 0; i < N; i++) {
    const omega = 1.0 + baseOmegas[i] * spread;
    let dtheta = omega;
    dtheta += K * r * Math.sin(psi - phases[i]);
    if (extStrength > 0) {
      dtheta += extStrength * Math.sin(extPhase - phases[i]);
    }
    if (leaderPresent) {
      const leaderK = 0.5;
      dtheta += leaderK * Math.sin(leaderPhase - phases[i]);
    }
    let np = phases[i] + dtheta * dt;
    np = np % (2 * Math.PI);
    if (np < 0) np += 2 * Math.PI;
    if (np < phases[i] && phases[i] > 5.5) {
      newFlashCounts[i] += 1;
    }
    newPhases[i] = np;
  }
  let sumCos2=0,sumSin2=0;
  for(let i=0;i<N;i++){ sumCos2+=Math.cos(newPhases[i]); sumSin2+=Math.sin(newPhases[i]); }
  const rNew = Math.sqrt(sumCos2*sumCos2+sumSin2*sumSin2)/Math.max(1,N);
  const alpha = 0.008;
  const smoothedR = state.smoothedR * (1-alpha) + rNew * alpha;
  return {
    phases: newPhases,
    baseOmegas: baseOmegas,
    xs: xs,
    ys: ys,
    t: state.t + dt,
    leaderPhase: leaderPhase,
    leaderOmega: state.leaderOmega,
    flashCounts: newFlashCounts,
    lastR: rNew,
    lastPsi: psi,
    smoothedR: smoothedR
  };
};
exports.observe = (state, params) => {
  const N = state.phases.length;
  const trueR = state.lastR ?? 0;
  const t = state.t ?? 0;
  const ramp = Math.min(1, t / 45);
  const timeFactor = 0.35 + 0.65 * ramp;
  const rObs = Math.max(0, Math.min(1, trueR * timeFactor + 0.02 * ramp * (trueR > 0.3 ? 1 : 0)));
  let psi = state.lastPsi ?? 0;
  let syncCount = 0;
  for (let i = 0; i < N; i++) {
    let diff = Math.abs(state.phases[i] - psi);
    diff = Math.min(diff, 2 * Math.PI - diff);
    if (diff < 0.5) syncCount++;
  }
  const sync_fraction = syncCount / Math.max(1,N);
  const totalFlashes = state.flashCounts.reduce((a, b) => a + b, 0);
  const mean_flash_rate = state.t > 0 ? totalFlashes / state.t / Math.max(1,N) : 0;
  return {
    order_parameter_r: rObs,
    sync_fraction: sync_fraction,
    mean_flash_rate: mean_flash_rate,
    total_fireflies: N,
    external_cue_level: params.externalCue ?? 0,
    leader_visible: params.leaderPresent ? 1 : 0
  };
};
exports.view = (state, params) => {
  const N = state.phases.length;
  const agents = [];
  for (let i = 0; i < N; i++) {
    const phase = state.phases[i];
    const tint = (phase % (2 * Math.PI)) / (2 * Math.PI);
    const isFlashing = phase < 0.35 || phase > 2 * Math.PI - 0.35;
    let sprite = "firefly";
    if (params.leaderPresent && i === 0) sprite = "leaderFirefly";
    agents.push({
      id: "f" + i,
      x: state.xs[i],
      y: state.ys[i],
      tint: isFlashing ? 1 : tint * 0.7 + 0.15,
      sprite: sprite,
      bubble: isFlashing ? "✦" : undefined
    });
  }
  return { kind: "population", agents: agents };
};
